      "most_likely_effort": 20
    },
    {
      "activity_id": "A4",
      "activity_name": "Setup CI infrastructure for s-c-d repo",
      "activity_description": "Configure continuous integration infrastructure for the spring-cloud-data repository to build on every commit (U3).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A5",
      "activity_name": "Resolve and add module dependent JARs to Boot loader",
      "activity_description": "Develop an approach to resolve and add module-dependent JARs (e.g., database drivers) to the Spring Boot loader for OOTB modules (U4).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A6",
      "activity_name": "Bootify ModuleLauncher",
      "activity_description": "Refactor ModuleLauncher to use Spring Boot's support for properties, settings, and future CP augmentation (U5).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7",
      "activity_name": "Investigate PHD porting for HDFS module",
